"""Load independently authored public fixture constants for mapping tests."""

import json
from pathlib import Path
from typing import Any

from coleman.core.actions import RankingAction, RankingSpace
from coleman.core.decisions import Decision
from coleman.core.identity import Reference
from coleman.core.sampling import SamplingRecord
from coleman.problems.tcpci import TcpciProblem

FIXTURES = Path(__file__).parents[1] / "fixtures" / "tcpci" / "v1"


def data(name: str = "problem") -> dict[str, Any]:
    """Read fresh raw hand-authored JSON data, never generated by the SUT."""
    return json.loads((FIXTURES / f"{name}.json").read_text(encoding="utf-8"))


def problem() -> TcpciProblem:
    """Read the strict declared ABC planning opportunity."""
    return TcpciProblem.from_json((FIXTURES / "problem.json").read_bytes())


def ref(name: str) -> Reference:
    """Return one explicit synthetic v1 reference."""
    return Reference(id=name, version="1")


def proposal(value: TcpciProblem, order: str = "BAC", *, sampled: bool = False) -> Decision:
    """Bind an explicit complete ranking and its declared original mass."""
    space = value.semantic.request.space
    if not isinstance(space, RankingSpace):
        raise ValueError("Fixture requires a ranking request")
    action = RankingAction(schema_version=1, space=space, order=tuple(ref(name) for name in order))
    return Decision(
        schema_version=1,
        request=value.semantic.request,
        implementation=ref("authored-priority-ranking"),
        action=action,
        sampling=SamplingRecord(
            mechanism="sampled" if sampled else "deterministic",
            mechanism_ref=ref("authored-priority-rule"),
            status="exact",
            action_fingerprint=action.fingerprint,
            probability=0.125 if sampled else 1.0,
        ),
        state_owner="stateless",
    )
